parameters.text:
=Summarize these release notes in 2-3 concise sentences for a design system team. Do not use markdown headers.

Release: {{ $('Prepare Release Data').item.json.name }}
Repository: {{ $('Prepare Release Data').item.json.repo }}

Release notes:
{{ $('Prepare Release Data').item.json.body }}

parameters.jsCode:
const release = $('Prepare Release Data').first().json;
const agentOutput = $input.first().json;
const summary = agentOutput.output
  ?? agentOutput.text
  ?? agentOutput.message?.content
  ?? agentOutput.response
  ?? `${release.name} is ready for review.`;

const WEBHOOK_BASE = 'https://flows-webhook.stage.trimble-ai.com/agentic/workflows/v1/webhook';
const APPROVAL_KEY = 'change-me-to-a-random-secret';
const WEBHOOK_AUTH_TOKEN = 'PASTE_TRIMBLE_TOKEN_HERE';

const staticData = $getWorkflowStaticData('global');
staticData.pending = staticData.pending || {};

const approvalId = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
staticData.pending[approvalId] = {
  ...release,
  summary,
  createdAt: Date.now(),
};

const authQuery = WEBHOOK_AUTH_TOKEN
  ? `&access_token=${encodeURIComponent(WEBHOOK_AUTH_TOKEN)}`
  : '';
const approveUrl = `${WEBHOOK_BASE}/modus-wc-release-approve?id=${approvalId}&key=${APPROVAL_KEY}${authQuery}`;
const rejectUrl = `${WEBHOOK_BASE}/modus-wc-release-reject?id=${approvalId}&key=${APPROVAL_KEY}${authQuery}`;

const card = {
  cardsV2: [
    {
      cardId: `release-${release.version}`,
      card: {
        header: {
          title: release.name,
          subtitle: 'Release notes ready for review',
          imageUrl: 'https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png',
          imageType: 'CIRCLE',
        },
        sections: [
          {
            header: 'Summary',
            widgets: [{ textParagraph: { text: summary } }],
          },
          {
            header: 'Details',
            collapsible: true,
            widgets: [
              { textParagraph: { text: String(release.body || '').substring(0, 3500) } },
              {
                buttonList: {
                  buttons: [
                    { text: 'Approve & Post to Group', onClick: { openLink: { url: approveUrl } } },
                    { text: 'Reject', onClick: { openLink: { url: rejectUrl } } },
                  ],
                },
              },
              {
                buttonList: {
                  buttons: [
                    { text: 'View on GitHub', onClick: { openLink: { url: release.releaseUrl } } },
                  ],
                },
              },
            ],
          },
        ],
      },
    },
  ],
};

return [{ json: { ...release, summary, approvalId, reviewCard: card } }];

parameters.responseBody:
={
  "ok": true,
  "message": "Release review sent to Google Chat",
  "version": "{{ $('Prepare Release Data').item.json.version }}"
}

parameters.jsCode:
const APPROVAL_KEY = 'change-me-to-a-random-secret';
const query = $json.query || {};
const approvalId = query.id;
const key = query.key;

if (!approvalId || key !== APPROVAL_KEY) {
  throw new Error('Invalid or missing approval token.');
}

const staticData = $getWorkflowStaticData('global');
const pending = staticData.pending || {};
const release = pending[approvalId];

if (!release) {
  throw new Error('Approval request not found or already processed.');
}

delete pending[approvalId];

return [{ json: release }];

